# ------------------------------------------------------------------ admin dashboard (demo, not linked in public nav)
def stat(icn, label, val, delta, up=True):
    return '<li class="kpi"><span class="kpi__icon">%s</span><div><p class="kpi__label">%s</p><p class="kpi__val">%s</p><p class="kpi__delta %s">%s</p></div></li>' % (ic(icn), label, val, 'is-up' if up else 'is-down', delta)


def badge_status(s):
    m = {'New': 'info', 'Quoted': 'warn', 'In review': 'muted', 'Won': 'ok', 'Lost': 'bad', 'Published': 'ok', 'Draft': 'muted', 'Active': 'ok', 'Invited': 'warn', 'Read': 'muted', 'Unread': 'info'}
    return '<span class="pill pill--%s">%s</span>' % (m.get(s, 'muted'), s)


def table(cols, rows, label, cls='', sortable=False):
    o = '<div class="table-wrap" tabindex="0" role="region" aria-label="%s"><table class="table table--stack %s"><caption class="sr-only">%s</caption><thead><tr>%s</tr></thead><tbody>' % (label, cls, label, ''.join('<th scope="col">%s</th>' % c for c in cols))
    for r in rows:
        o += '<tr>' + ''.join(('<th scope="row" data-label="%s">%s</th>' if i == 0 else '<td data-label="%s">%s</td>') % (cols[i], c) for i, c in enumerate(r)) + '</tr>'
    return o + '</tbody></table></div>'


